shared/api is not merged yet. The catalog still loads courses like this, and tsc --strict compiles it without errors:

async function getCourses(query: CatalogQuery): Promise<CoursePage> {
    const res = await fetch(`/api/courses?${toSearchParams(query)}`);
    return (await res.json()) as CoursePage;
}

Network panel, GET /api/courses?page=1 -> 200, content-type: application/json:

{"items":[{"id":"web-http-fundamentals","title":"Web Application Fundamentals","level":"Beginner","tags":["http"],"rating":4.7,"learners":1280,"updatedAt":"2026-09-14"}],"total":1}

Statement: "Because getCourses returns Promise<CoursePage> and the project compiles with --strict, every course the catalog receives at runtime has a level of beginner, intermediate or advanced."

After the refactor the catalog shows errors with:

type ApiError =
    | { kind: "network" }
    | { kind: "unauthorized" }
    | { kind: "validation"; fieldErrors: Record<string, string> }
    | { kind: "server"; status: number };

function assertNever(value: never): never {
    throw new Error(`unexpected: ${JSON.stringify(value)}`);
}

function describeError(error: ApiError): string {
    switch (error.kind) {
        case "network": return "Cannot reach CodeDev.";
        case "unauthorized": return "Please sign in again.";
        case "validation": return "Please fix the highlighted fields.";
        case "server": return `CodeDev is having a problem (${error.status}).`;
        default: return assertNever(error);
    }
}

A teammate adds | { kind: "conflict"; message: string } to ApiError for the 409 that POST /api/enrollments sends, and does not touch describeError.

Statement: "tsc --strict now reports an error at assertNever(error), because in the default branch error can still be the conflict variant, which is not assignable to never."
